package lru_test

import (
	"testing"

	"github.com/ai-verification/go-lru-cache/internal/lru"
)

func TestBasicPutGet(t *testing.T) {
	c := lru.New(2)
	c.Put("a", "1")
	c.Put("b", "2")
	v, ok := c.Get("a")
	if !ok || v != "1" {
		t.Fatalf("expected a=1, got %q ok=%v", v, ok)
	}
}

func TestEviction(t *testing.T) {
	c := lru.New(2)
	c.Put("a", "1")
	c.Put("b", "2")
	c.Put("c", "3") // evicts "a" (LRU)
	_, ok := c.Get("a")
	if ok {
		t.Fatal("expected 'a' to be evicted")
	}
	v, ok := c.Get("b")
	if !ok || v != "2" {
		t.Fatalf("expected b=2, got %q ok=%v", v, ok)
	}
	v, ok = c.Get("c")
	if !ok || v != "3" {
		t.Fatalf("expected c=3, got %q ok=%v", v, ok)
	}
}

func TestGetPromotesRecency(t *testing.T) {
	c := lru.New(2)
	c.Put("a", "1")
	c.Put("b", "2")
	c.Get("a")      // promote a
	c.Put("c", "3") // should evict "b", not "a"
	_, ok := c.Get("b")
	if ok {
		t.Fatal("expected 'b' to be evicted after promoting 'a'")
	}
	v, ok := c.Get("a")
	if !ok || v != "1" {
		t.Fatalf("expected a=1 after promotion, got %q ok=%v", v, ok)
	}
}

func TestOverwriteKey(t *testing.T) {
	c := lru.New(2)
	c.Put("x", "old")
	c.Put("x", "new")
	v, ok := c.Get("x")
	if !ok || v != "new" {
		t.Fatalf("expected x=new, got %q ok=%v", v, ok)
	}
	if c.Len() != 1 {
		t.Fatalf("expected len=1 after overwrite, got %d", c.Len())
	}
}

func TestLenAndCap(t *testing.T) {
	c := lru.New(3)
	if c.Len() != 0 {
		t.Fatalf("expected initial len=0, got %d", c.Len())
	}
	if c.Cap() != 3 {
		t.Fatalf("expected cap=3, got %d", c.Cap())
	}
	c.Put("a", "1")
	if c.Len() != 1 {
		t.Fatalf("expected len=1, got %d", c.Len())
	}
}

func TestMissReturnsOk(t *testing.T) {
	c := lru.New(2)
	_, ok := c.Get("missing")
	if ok {
		t.Fatal("expected false for missing key")
	}
}
